import openpyxl
import os

wb = openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws = wb.active

# Compute sums from the table (C3:I9)
sums = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'E': 0, 'F': 0, 'G': 0}
for row in range(3, 10):
    for col in range(3, 10):
        cell = ws.cell(row=row, column=col).value
        if cell and isinstance(cell, str) and len(cell) >= 2:
            letter = cell[0].upper()
            try:
                num = int(cell[1:])
            except ValueError:
                continue
            if letter in sums:
                sums[letter] += num

# Write results to B11:B17
for i, letter in enumerate(['A', 'B', 'C', 'D', 'E', 'F', 'G']):
    ws.cell(row=11 + i, column=2, value=sums[letter])

wb.save(os.environ['OUT_XLSX'])
print("Done. Sums:", sums)
